const zh=document.documentElement.lang.startsWith('zh'),el=id=>document.getElementById('M35-'+id),tr=(z,e)=>zh?z:e;
let layer=0,z1=.5,z2=-.5,timer=null;
function apply(x,which,inverse){const item=data.weights[which];let a=[x[item.keep]];item.layers.forEach((l,k)=>{a=l.bias.map((b,i)=>b+l.weight[i].reduce((s,w,j)=>s+w*a[j],0));if(k<2)a=a.map(Math.tanh);});const scale=.8*Math.tanh(a[0]),shift=a[1],y=x.slice(),j=1-item.keep;y[j]=inverse?x[j]*Math.exp(scale)+shift:(x[j]-shift)*Math.exp(-scale);return {x:y,ld:inverse?scale:-scale};}
function compute(){let x=[z1,z2],logdet=0,path=[x.slice()];for(let n=0;n<layer;n++){let result=apply(x,7-n,true);x=result.x;logdet+=result.ld;path.push(x.slice());}let back=x.slice();for(let n=8-layer;n<8;n++)back=apply(back,n,false).x;return {x:x[0],y:x[1],logdet,area:Math.exp(logdet),density:Math.exp(-.5*(z1*z1+z2*z2)-logdet)/(2*Math.PI),error:Math.max(Math.abs(back[0]-z1),Math.abs(back[1]-z2)),path};}
function state(){const d=compute();return {layer,z1,z2,x:d.x,y:d.y,logdet:d.logdet,area:d.area,density:d.density,error:d.error,playing:timer!==null};}
function render(){const d=compute(),svg=el('board');let s='<defs><clipPath id="M35-left"><rect x="55" y="55" width="350" height="350"/></clipPath><clipPath id="M35-right"><rect x="555" y="55" width="350" height="350"/></clipPath></defs>';const text=(x,y,t,size=14,c='#29424d',anchor='start')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${c}" text-anchor="${anchor}">${t}</text>`;
 const X=(v,p)=>55+p*500+(v+5)*35,Y=v=>55+(7-v)*35;
 for(let panel=0;panel<2;panel++){
  s+=text(55+panel*500,28,panel?tr('生成方向：已通过 ','Generation: ')+layer+tr(' 层',' layers'):tr('标准高斯起点','Standard-normal starting space'),18)+`<text x="${19+panel*500}" y="230" transform="rotate(-90 ${19+panel*500} 230)" font-size="14" text-anchor="middle" fill="#29424d">${panel?'x2':'z2'}</text>`;
  for(let v=-4;v<=4;v+=2){s+=`<path d="M${X(v,panel)} 55V405" stroke="#e1e7e6"/>`+text(X(v,panel),426,v,12,'#4a626d','middle');}
  for(let v=-3;v<=7;v+=2){s+=`<path d="M${55+panel*500} ${Y(v)}h350" stroke="#e1e7e6"/>`+text(47+panel*500,Y(v)+4,v,12,'#4a626d','end');}
  s+='<g clip-path="url(#M35-'+(panel?'right':'left')+')">';const frame=data.frames[panel?layer:0];
  frame.grid.forEach(line=>s+=`<polyline points="${line.map(a=>X(a[0],panel)+','+Y(a[1])).join(' ')}" fill="none" stroke="#1b6e8c" stroke-width="1.2" opacity=".8"/>`);
  frame.points.forEach(a=>s+=`<circle cx="${X(a[0],panel)}" cy="${Y(a[1])}" r="2" fill="#c07c3b" opacity=".65"/>`);
  if(panel&&layer>0)s+=`<polyline points="${d.path.map(a=>X(a[0],panel)+','+Y(a[1])).join(' ')}" fill="none" stroke="#b34c49" stroke-width="2" stroke-dasharray="4 3"/>`;
  const px=panel?d.x:z1,py=panel?d.y:z2;s+=`<circle cx="${X(px,panel)}" cy="${Y(py)}" r="6" fill="#af3f40" stroke="white" stroke-width="2"/></g>`+text(230+panel*500,450,panel?'x1':'z1',14,'#29424d','middle');
 }
 s+=text(55,482,`z = (${z1.toFixed(2)}, ${z2.toFixed(2)})`,15)+text(555,482,`x = (${d.x.toFixed(4)}, ${d.y.toFixed(4)})`,15);
 svg.innerHTML=s;el('layer').value=layer;el('z1').value=z1;el('z2').value=z2;el('play').textContent=timer?tr('暂停','Pause'):tr('播放','Play');
 el('status').textContent=tr('面积比 ','Area ratio ')+d.area.toFixed(6)+`; log|det|=${d.logdet.toFixed(6)}; `+tr('密度 ','density ')+d.density.toFixed(6)+tr('；逆向恢复误差 ','; inverse-recovery error ')+d.error.toExponential(2);}
function pause(){if(timer!==null)clearInterval(timer);timer=null;}
function set(o={}){pause();if(o.layer!==undefined)layer=Math.max(0,Math.min(8,Math.round(o.layer)));if(o.z1!==undefined)z1=Math.max(-2,Math.min(2,+o.z1));if(o.z2!==undefined)z2=Math.max(-2,Math.min(2,+o.z2));render();return state();}
function reset(){pause();layer=0;z1=.5;z2=-.5;render();return state();}
el('layer').oninput=e=>set({layer:+e.target.value});el('z1').oninput=e=>set({z1:+e.target.value});el('z2').oninput=e=>set({z2:+e.target.value});el('back').onclick=()=>set({layer:layer-1});el('step').onclick=()=>set({layer:layer+1});el('reset').onclick=reset;
el('play').onclick=()=>{if(timer!==null){pause();render();return;}if(layer===8)layer=0;timer=setInterval(()=>{layer++;if(layer>=8)pause();render();},600);render();};
window.CourseLab={state,set,reset,destroy:pause};reset();

